  const pattern = PILOT.patterns[trip.p];
  const names = [leg.from, ...leg.segments.map(segment => segment.to)];
  const i = pattern.names.findIndex((n,i) => n === leg.from && (trip.d[i]-leg.dep)%86400 === 0 &&
    names.every((name,index) => pattern.names[i+index] === name));
  if (i < 0) return [];
