    const marginX=Math.min(width*0.16,76), marginY=Math.min(height*0.25,70);
    const scale=Math.min((width-2*marginX)/Math.max(1,bounds[2]-bounds[0]),(height-2*marginY)/Math.max(1,bounds[3]-bounds[1]),8)*zoom;
    const dx=width/2-scale*(bounds[2]+bounds[0])/2,dy=height/2-scale*(bounds[3]+bounds[1])/2;
    const project=([x,y])=>[x*scale+dx,y*scale+dy];
    const world=svg('g',{transform:`translate(${dx} ${dy}) scale(${scale})`},image);
    const stroke=(d,color,size,parent=world,extra={})=>svg('path',{d,fill:'none',stroke:color,'stroke-width':size,'stroke-linejoin':'round','stroke-linecap':'round','vector-effect':'non-scaling-stroke',...extra},parent);
    const wide=bounds[0]<88 || bounds[1]<77 || bounds[2]>439 || bounds[3]>278;
    if (wide) {
      for(const pattern of Object.values(PILOT.patterns)) {
        const xy=pattern.ids.map(id=>stopPositions[id]).filter(Boolean);
        if(xy.length>1) stroke(pathThrough(xy),'#c6cabb',2);
      }
    }
    for(const [layer,color] of [['buildings','#dedfd5'],['parks','#c5d2bc'],['water','#b7d4d5']])
      if(streetLayers[layer]) svg('path',{d:streetLayers[layer],fill:color},world);
    for (const [layer,color,size] of [['streets','#fafaf3',1.65],['avenues','#d4d4c6',4],['avenues','#fffcf4',2.6],
      ['arteries','#d5ccae',6.2],['arteries','#fff3cc',4.4],['rail','#bebfb1',1.5]])
      if(streetLayers[layer]) stroke(streetLayers[layer],color,Math.min(size,Math.max(0.6,size*scale/1.6)));
