    for (const route of routes) {
      stroke(pathThrough(route),'#fffdf4',8.5,image); stroke(pathThrough(route),'#24664e',5,image);
      for(const [x,y] of route.slice(1,-1)) svg('circle',{cx:x,cy:y,r:3.4,fill:'#fffdf5',stroke:'#24664e','stroke-width':2},image);
    }
    const marked=[{point:routes[0][0],name:legs[0][0].name,mark:'A'},
      {point:routes.at(-1).at(-1),name:legs.at(-1).at(-1).name,mark:'B'}];
    if(legs.length>1) marked.push({point:routes[1][0],name:legs[1][0].name,mark:'↔'});
    const boxes=[[0,0,114,50],[width-46,0,width,54],[0,height-25,width,height]];
    function intersects(a,b){return a[0]<b[2] && a[2]>b[0] && a[1]<b[3] && a[3]>b[1]}
    for(const {point:[x,y],name,mark} of marked) {
      svg('circle',{cx:x,cy:y,r:11,stroke:'#fffcf3','stroke-width':2.6,fill:'#173e32'},image);
      svg('text',{x,y:y+3.8,'text-anchor':'middle','font-size':10.8,'font-weight':700,fill:'white'},image,mark);
      if(x<0 || x>width || y<0 || y>height)continue;
      const short=name.replace(/ \(Metro Station\)$/,'').replace(/ Metro Station$/,'').split(' / ')[0];
      const text=svg('text',{x,y,'font-size':12,'font-weight':700,fill:'#183c2f','paint-order':'stroke',stroke:'#f5f6eb','stroke-width':3.6,'stroke-linejoin':'round'},image,short);
      const w=text.getComputedTextLength();
      const left=Math.max(6,Math.min(width-w-6,x-w/2));
      const base=mark==='A'?y-18:y+26;
      const cy=[base,mark==='A'?y+25:y-18].find(c=>c>12 && c<height-21 && !boxes.some(b=>intersects(b,[left,c-12,left+w,c+2])));
      if(cy===undefined){text.remove();continue}
      text.setAttribute('x',left);text.setAttribute('y',cy); boxes.push([left-4,cy-15,left+w+4,cy+5]);
    }
